using Microsoft.Build.Framework;
using System;
using System.Globalization;
using System.IO;
using System.Text;

/// <summary>
/// Writes the Serenity static assets manifest (see Serenity.Web.SerenityStaticAssets), a JSON array of the asset
/// folders with their BasePath, Root and optional Includes / Excludes / WellKnown / WellKnownExcludes patterns.
/// The file is only written when its contents change.
/// </summary>
public class WriteStaticAssetsManifestTask : Microsoft.Build.Utilities.Task
{
    /// <summary>Asset folders, with BasePath and optional pattern metadata</summary>
    [Microsoft.Build.Framework.Required]
    public ITaskItem[] Roots { get; set; }

    [Microsoft.Build.Framework.Required]
    public string File { get; set; }

    public override bool Execute()
    {
        var sb = new StringBuilder();
        sb.Append("[");
        for (var i = 0; i < Roots.Length; i++)
        {
            var root = Roots[i];
            sb.Append(i == 0 ? "\r\n  {" : ",\r\n  {");
            Append(sb, "BasePath", root.GetMetadata("BasePath"), first: true);
            Append(sb, "Root", root.GetMetadata("FullPath"));
            Append(sb, "Includes", root.GetMetadata("Includes"));
            Append(sb, "Excludes", root.GetMetadata("Excludes"));
            if (string.Equals(root.GetMetadata("WellKnown"), "true", StringComparison.OrdinalIgnoreCase))
            {
                sb.Append(", \"WellKnown\": true");
                Append(sb, "WellKnownExcludes", root.GetMetadata("WellKnownExcludes"));
            }
            sb.Append(" }");
        }
        sb.Append("\r\n]\r\n");

        var content = sb.ToString();
        if (System.IO.File.Exists(File) && System.IO.File.ReadAllText(File) == content)
            return true;

        var directory = Path.GetDirectoryName(File);
        if (!string.IsNullOrEmpty(directory))
            Directory.CreateDirectory(directory);

        System.IO.File.WriteAllText(File, content);
        return true;
    }

    private static void Append(StringBuilder sb, string name, string value, bool first = false)
    {
        if (!first && string.IsNullOrEmpty(value))
            return;

        sb.Append(first ? " \"" : ", \"").Append(name).Append("\": \"");
        foreach (var c in value ?? "")
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\r': sb.Append("\\r"); break;
                case '\n': sb.Append("\\n"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < ' ')
                        sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else
                        sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }
}
